// Chain diagrams: the pure rule model of decision nodes (UI/js/components/flow-rules.js).
// describe / validate / evaluate for every source and operator, the regex guard, the envelope heuristics, and parity
// with Cores/Services/flow_rules.py (the GOLDEN block at the end was produced by the Python evaluator).
const path=require("path")
const ROOT=path.resolve(__dirname,"..","..")
const R=require(path.join(ROOT,"UI","js","components","flow-rules.js"))
let passed=0,failed=0
function check(name,cond,detail){if(cond){passed++;return}failed++;console.log("  FAIL  "+name+(detail?"  ->  "+detail:""))}
function eq(name,a,b){check(name,JSON.stringify(a)===JSON.stringify(b),JSON.stringify(a)+" != "+JSON.stringify(b))}
const cond=(source,op,value,extra)=>Object.assign({source:source,field:"",op:op,value:value===undefined?"":value,ci:true},extra||{})
const ev=(c,data,scope)=>R.flowRuleEvaluate(c,data,scope).result
const PING_UP={stdout:"64 bytes from 10.0.0.5: icmp_seq=1 ttl=64 time=0.3 ms\n2 packets transmitted, 2 received, 0% packet loss",stderr:"",exit_code:0,parsed:null}
const PING_DOWN={stdout:"PING 10.0.0.9\n2 packets transmitted, 0 received, 100% packet loss",stderr:"",exit_code:1,parsed:null}
const NMAP={stdout:"Host is up (0.01s latency).\nPORT    STATE SERVICE\n22/tcp  open  ssh\n80/tcp  open  http\n443/tcp closed https\n8080/tcp open|filtered x\n",stderr:"",exit_code:0,parsed:null}
// ---- model tables
const ALL_OPS=["contains","not_contains","equals","not_equals","starts_with","ends_with","regex","not_regex","eq","ne","gt","ge","lt","le","is_empty","not_empty","is_true","is_false"]
const ALL_SOURCES=["exit_code","stdout","stderr","output","var","parsed","line_count","match_count","port_open","host_up"]
eq("ops: the spec's operator list",Object.keys(R.FLOW_RULE_OPS).sort(),ALL_OPS.slice().sort())
eq("sources: the spec's source list",R.FLOW_RULE_SOURCES.map((s)=>s.id).sort(),ALL_SOURCES.slice().sort())
check("sources: every offered op exists and the default op is offered",R.FLOW_RULE_SOURCES.every((s)=>s.ops.length&&s.ops.every((o)=>R.FLOW_RULE_OPS[o])&&s.ops.indexOf(s.op)!==-1&&s.label&&s.subject))
eq("sources: exit code and counts compare numbers only",[R.flowRuleSource("exit_code").ops,R.flowRuleSource("line_count").ops,R.flowRuleSource("match_count").ops],[R.FLOW_RULE_NUM_OPS,R.FLOW_RULE_NUM_OPS,R.FLOW_RULE_NUM_OPS])
eq("sources: port_open and host_up are yes/no",[R.flowRuleSource("port_open").ops,R.flowRuleSource("host_up").ops],[["is_true","is_false"],["is_true","is_false"]])
eq("sources: fields",ALL_SOURCES.map((s)=>R.flowRuleSource(s).field),["","","","","name","path","","regex","",""])
check("sources: unknown id",R.flowRuleSource("nope")===null)
eq("default rule",R.flowRuleDefault(),{source:"output",field:"",op:"contains",value:"",ci:true})
eq("default rule per source",[R.flowRuleDefault("exit_code"),R.flowRuleDefault("host_up")],[{source:"exit_code",field:"",op:"eq",value:"0",ci:true},{source:"host_up",field:"",op:"is_true",value:"",ci:true}])
eq("default branch",R.flowBranchDefault("alive"),{name:"alive",match:"all",conditions:[{source:"output",field:"",op:"contains",value:"",ci:true}]})
check("default branch: fresh condition objects",R.flowBranchDefault("a").conditions[0]!==R.flowBranchDefault("a").conditions[0])
eq("normalize: fills the COND shape",R.flowRuleNormalize({source:"stdout",value:5}),{source:"stdout",field:"",op:"",value:"5",ci:true})
eq("normalize: ci only false when false",[R.flowRuleNormalize({ci:false}).ci,R.flowRuleNormalize({ci:0}).ci,R.flowRuleNormalize(null).ci],[false,true,true])
eq("needs value",[cond("output","contains"),cond("output","is_empty"),cond("host_up","is_true"),cond("port_open","is_true"),cond("exit_code","eq"),cond("var","is_true")].map(R.flowRuleNeedsValue),[true,false,false,true,true,false])
eq("ci toggle only for text compares",[cond("output","contains"),cond("output","regex"),cond("output","is_empty"),cond("exit_code","eq"),cond("match_count","ge"),cond("host_up","is_true"),cond("var","eq"),cond("var","equals")].map(R.flowRuleUsesCi),[true,true,false,false,true,false,false,true])
eq("switch source: keeps a still-valid op and value",R.flowRuleWithSource(cond("stdout","contains","ttl="),"output"),{source:"output",field:"",op:"contains",value:"ttl=",ci:true})
eq("switch source: resets op and value that no longer fit",R.flowRuleWithSource(cond("stdout","contains","ttl="),"exit_code"),{source:"exit_code",field:"",op:"eq",value:"0",ci:true})
eq("switch source: host_up drops the value",R.flowRuleWithSource(cond("stdout","contains","ttl="),"host_up"),{source:"host_up",field:"",op:"is_true",value:"",ci:true})
eq("switch source: clears a field of another kind",R.flowRuleWithSource(cond("match_count","ge","1",{field:"\\d+"}),"var").field,"")
eq("switch source: unknown source changes nothing",R.flowRuleWithSource(cond("stdout","contains","x"),"nope").source,"stdout")
// ---- describe
eq("describe: the spec example",R.flowRuleDescribe(cond("output","contains","ttl=")),"output contains 'ttl='")
eq("describe: text ops",["not_contains","equals","not_equals","starts_with","ends_with"].map((o)=>R.flowRuleDescribe(cond("stdout",o,"x"))),["stdout does not contain 'x'","stdout is 'x'","stdout is not 'x'","stdout starts with 'x'","stdout ends with 'x'"])
eq("describe: regex ops",[R.flowRuleDescribe(cond("stderr","regex","^err")),R.flowRuleDescribe(cond("stderr","not_regex","^err"))],["stderr matches /^err/","stderr does not match /^err/"])
eq("describe: numeric ops",["eq","ne","gt","ge","lt","le"].map((o)=>R.flowRuleDescribe(cond("exit_code",o,"0"))),["exit code = 0","exit code != 0","exit code > 0","exit code >= 0","exit code < 0","exit code <= 0"])
eq("describe: empty / true",[R.flowRuleDescribe(cond("output","is_empty")),R.flowRuleDescribe(cond("output","not_empty")),R.flowRuleDescribe(cond("var","is_true","",{field:"found"})),R.flowRuleDescribe(cond("var","is_false","",{field:"found"}))],["output is empty","output is not empty","variable found is true","variable found is false"])
eq("describe: var / parsed / counts",[R.flowRuleDescribe(cond("var","equals","x",{field:"name"})),R.flowRuleDescribe(cond("parsed","contains","80",{field:"ports[*].port"})),R.flowRuleDescribe(cond("parsed","not_empty")),R.flowRuleDescribe(cond("line_count","gt","3")),R.flowRuleDescribe(cond("match_count","ge","2",{field:"open"}))],["variable name is 'x'","parsed ports[*].port contains '80'","parsed data is not empty","number of output lines > 3","matches of /open/ >= 2"])
eq("describe: port_open / host_up",[R.flowRuleDescribe(cond("port_open","is_true","443")),R.flowRuleDescribe(cond("port_open","is_false","443")),R.flowRuleDescribe(cond("port_open","is_true","")),R.flowRuleDescribe(cond("host_up","is_true")),R.flowRuleDescribe(cond("host_up","is_false"))],["port 443 is open","port 443 is not open","port ? is open","host is up","host is down"])
eq("describe: long values are cut at 60",R.flowRuleDescribe(cond("output","contains","y".repeat(80))),"output contains '"+"y".repeat(60)+"...'")
eq("describe: not an object",[R.flowRuleDescribe(null),R.flowRuleDescribe("x")],["invalid condition","invalid condition"])
eq("describe: missing numeric value",R.flowRuleDescribe(cond("exit_code","eq","")),"exit code = ?")
eq("describe branch: all / any / none",[R.flowBranchDescribe({match:"all",conditions:[cond("host_up","is_true"),cond("exit_code","eq","0")]}),R.flowBranchDescribe({match:"any",conditions:[cond("port_open","is_true","80"),cond("port_open","is_true","443")]}),R.flowBranchDescribe({match:"all",conditions:[]})],["host is up and exit code = 0","port 80 is open or port 443 is open","(no conditions)"])
eq("describe decision: the preview sentence",R.flowDecisionDescribe({branches:[{name:"alive",match:"all",conditions:[cond("output","contains","ttl=")]}],else:"down"}),"If output contains 'ttl=' -> alive\nOtherwise -> down")
eq("describe decision: several branches",R.flowDecisionDescribe({branches:[{name:"web",match:"any",conditions:[cond("port_open","is_true","80"),cond("port_open","is_true","443")]},{name:"ssh",match:"all",conditions:[cond("port_open","is_true","22")]}],else:"none"}),"If port 80 is open or port 443 is open -> web\nOtherwise if port 22 is open -> ssh\nOtherwise -> none")
eq("describe decision: no branches, default else",R.flowDecisionDescribe({}),"Always -> else")
// ---- validate
eq("validate: a complete rule per source",[cond("output","contains","x"),cond("stdout","regex","^a"),cond("stderr","is_empty"),cond("exit_code","eq","0"),cond("line_count","gt","2"),cond("match_count","ge","1",{field:"open"}),cond("var","equals","",{field:"n"}),cond("parsed","not_empty"),cond("port_open","is_true","443"),cond("host_up","is_false")].map(R.flowRuleValidate),["","","","","","","","","",""])
check("validate: unknown source / op",!!R.flowRuleValidate(cond("nope","contains","x"))&&!!R.flowRuleValidate(cond("output","nope","x")))
check("validate: text to look for is required",!!R.flowRuleValidate(cond("output","contains",""))&&!!R.flowRuleValidate(cond("output","starts_with","")))
check("validate: 'is exactly' may compare with nothing",R.flowRuleValidate(cond("output","equals",""))==="")
check("validate: numbers",!!R.flowRuleValidate(cond("exit_code","eq","abc"))&&!!R.flowRuleValidate(cond("exit_code","eq",""))&&R.flowRuleValidate(cond("exit_code","eq"," 2 "))===""&&R.flowRuleValidate(cond("exit_code","eq","${n}"))==="")
check("validate: var and match_count need a field",!!R.flowRuleValidate(cond("var","equals","x"))&&!!R.flowRuleValidate(cond("match_count","ge","1")))
check("validate: port range",["0","65536","abc","","8 0","-1"].every((v)=>!!R.flowRuleValidate(cond("port_open","is_true",v)))&&["1","65535","${item.port}"].every((v)=>R.flowRuleValidate(cond("port_open","is_true",v))===""))
check("validate: bad or dangerous regex",!!R.flowRuleValidate(cond("output","regex","(a+)+"))&&!!R.flowRuleValidate(cond("output","regex","("))&&!!R.flowRuleValidate(cond("output","regex",""))&&!!R.flowRuleValidate(cond("match_count","ge","1",{field:"(x*)*"})))
eq("validate decision: a good one",R.flowDecisionValidate({branches:[{name:"alive",match:"all",conditions:[cond("host_up","is_true")]}],else:"down"}),[])
const badDecision=R.flowDecisionValidate({branches:[{name:"a b",match:"all",conditions:[cond("host_up","is_true")]},{name:"dup",match:"x",conditions:[]},{name:"dup",match:"any",conditions:[cond("exit_code","eq","abc")]}],else:"dup"})
check("validate decision: bad name",badDecision.some((m)=>/Branch 1.*name must be/.test(m)),badDecision.join(" | "))
check("validate decision: ALL/ANY missing",badDecision.some((m)=>/Branch 2.*ALL or ANY/.test(m)))
check("validate decision: empty branch",badDecision.some((m)=>/Branch 2.*at least one condition/.test(m)))
check("validate decision: duplicate name",badDecision.some((m)=>/Branch 3.*used twice/.test(m)))
check("validate decision: condition problems carry their position",badDecision.some((m)=>/Branch 3 \(dup\), condition 1: Enter a number/.test(m)))
check("validate decision: else clashes with a branch",badDecision.some((m)=>/otherwise.*already used/.test(m)))
check("validate decision: else name required",R.flowDecisionValidate({branches:[],else:""}).length===1&&R.flowDecisionValidate({branches:[],else:"has space"}).length===1)
check("validate decision: limits",R.flowDecisionValidate({branches:Array.from({length:13},(_,i)=>({name:"b"+i,match:"all",conditions:[cond("host_up","is_true")]})),else:"else"}).some((m)=>/at most 12 branches/.test(m))&&R.flowDecisionValidate({branches:[{name:"b",match:"all",conditions:Array.from({length:13},()=>cond("host_up","is_true"))}],else:"else"}).some((m)=>/at most 12 conditions/.test(m)))
// ---- regex guard
eq("regex guard: safe patterns pass",["ttl=\\d+","^(\\d+)/(tcp|udp)\\s+open","(tcp|udp)+","(\\d|\\s)*","[(+*]+x","a{2,}","(?P<ip>\\d+\\.\\d+)","(?i)host is up","(?:ab)+c","(a|b)*"].map((p)=>R.flowRegexCheck(p)),["","","","","","","","","",""])
check("regex guard: nested repeats are refused",["(a+)+","(.*)*","((ab)+)+","(a{2,})+","(\\w+\\s?)*$","(a*)+b"].every((p)=>/nests one repeat/.test(R.flowRegexCheck(p))))
check("regex guard: overlapping alternatives are refused",/overlapping alternatives/.test(R.flowRegexCheck("(a|aa)*"))&&/overlapping alternatives/.test(R.flowRegexCheck("(a|ab|)+")))
check("regex guard: empty, too long, broken",/empty/.test(R.flowRegexCheck(""))&&/longer than 500/.test(R.flowRegexCheck("a".repeat(501)))&&/Invalid regex/.test(R.flowRegexCheck("(")))
check("regex guard: 500 characters is still allowed",R.flowRegexCheck("a".repeat(500))==="")
check("regex guard: too many groups",/too many groups/.test(R.flowRegexCheck("(a)".repeat(41))))
eq("regex translate: Python spellings",R.flowRegexTranslate("(?i)(?P<port>\\d+)/(?P=port)","m"),{pattern:"(?<port>\\d+)/\\k<port>",flags:"mi"})
check("regex compile: refuses what the guard refuses",(()=>{try{R.flowRegexCompile("(a+)+");return false}catch(e){return /nests/.test(e.message)}})())
check("regex compile: flags",R.flowRegexCompile("abc","i","g").flags.split("").sort().join("")==="gi")
check("evaluate: a refused regex is false with an error, never a hang",(()=>{const r=R.flowRuleEvaluate(cond("output","regex","(a+)+$"),{stdout:"a".repeat(40)+"!"});return r.result===false&&/nests/.test(r.error)})())
// ---- lookup / resolve / templates
const DATA={ports:[{port:80,service:"http"},{port:443,service:"https"}],a:{b:[1,{c:5}]},Name:"x",list:["p","q"]}
eq("lookup: paths",[R.flowLookup(DATA,"ports[*].port"),R.flowLookup(DATA,"a.b[1].c"),R.flowLookup(DATA,"a.b[-1].c"),R.flowLookup(DATA,"list.0"),R.flowLookup(DATA,"ports[0].service"),R.flowLookup(DATA,"$.a.b[0]"),R.flowLookup(DATA,"['Name']")],[[80,443],5,5,"p","http",1,"x"])
eq("lookup: keys fall back to case-insensitive",R.flowLookup(DATA,"name"),"x")
eq("lookup: missing or malformed is null",[R.flowLookup(DATA,"nope"),R.flowLookup(DATA,"a.b[9]"),R.flowLookup(DATA,"a..b"),R.flowLookup(null,"a"),R.flowLookup(DATA,"ports[*].nope")],[null,null,null,null,[]])
check("lookup: empty path is the value itself",R.flowLookup(DATA,"")===DATA)
eq("lookup: never walks the prototype",[R.flowLookup({},"__proto__"),R.flowLookup({},"constructor"),R.flowLookup([],"length"),R.flowLookup("str","length")],[null,null,null,null])
const SCOPE={vars:{name:"alice",n:5,last:"shadowed"},last:{stdout:"out",exit_code:3},target:{ipv4:"10.0.0.5"},item:{port:443},index:2}
eq("resolve: roots first, then variables",[R.flowResolve(SCOPE,"name"),R.flowResolve(SCOPE,"last.stdout"),R.flowResolve(SCOPE,"target.ipv4"),R.flowResolve(SCOPE,"item.port"),R.flowResolve(SCOPE,"index"),R.flowResolve(SCOPE,"vars.n"),R.flowResolve(SCOPE,"nope"),R.flowResolve(null,"name")],["alice","out","10.0.0.5",443,2,5,null,null])
