eq("escape: html and quotes",R.flowEscape("<img src=x onerror=\"a\"> & 'b'"),"&lt;img src=x onerror=&quot;a&quot;&gt; &amp; &#39;b&#39;")
eq("escape: null-safe",[R.flowEscape(null),R.flowEscape(undefined),R.flowEscape(0)],["","","0"])
