GOLDEN.conditions.forEach((g,i)=>{
const r=R.flowRuleEvaluate(g.cond,GOLDEN.datas[g.data],GOLDEN.scope)
const got={result:r.result,actual:r.actual,text:r.text,error:!!r.error}
if(JSON.stringify(got)!==JSON.stringify(g.want))parityBad.push(i+": "+JSON.stringify(g.cond)+" -> "+JSON.stringify(got)+" want "+JSON.stringify(g.want))
})
check("parity: "+GOLDEN.conditions.length+" recorded Python condition results",parityBad.length===0&&GOLDEN.conditions.length>100,parityBad.slice(0,3).join(" || "))
check("parity: the recorded set covers every source and every operator",ALL_SOURCES.every((s)=>GOLDEN.conditions.some((g)=>g.cond&&g.cond.source===s))&&ALL_OPS.every((o)=>GOLDEN.conditions.some((g)=>g.cond&&g.cond.op===o)))
parityBad=[]
GOLDEN.decisions.forEach((g,i)=>{
const r=R.flowDecisionEvaluate(g.cfg,GOLDEN.datas[g.data],GOLDEN.scope)
const got={branch:r.branch,trace:r.trace.map((t)=>({branch:t.branch,matched:t.matched,conditions:t.conditions.map((c)=>c.result)}))}
if(JSON.stringify(got)!==JSON.stringify(g.want))parityBad.push(i+": "+JSON.stringify(got)+" want "+JSON.stringify(g.want))
})
check("parity: "+GOLDEN.decisions.length+" recorded Python decision results",parityBad.length===0&&GOLDEN.decisions.length>10,parityBad.slice(0,3).join(" || "))
console.log("\nflow_rules: "+passed+" passed, "+failed+" failed")
